55	const PROCESSING_FEE = 5;
56	
57	const BASE_PREMIUM_BY_ITEM_TYPE: Record<string, number> = {
58	  sword: 100,
59	  amulet: 60,
60	  staff: 80,
61	  potion: 40,
62	  rune: 25,
63	  moonstone: 25,
64	};
65	
66	const basePremiumOf = (item: Item): number =>
67	  BASE_PREMIUM_BY_ITEM_TYPE[item.type];
68	
69	const policyBasePremiumOf = (items: readonly Item[]): number =>
70	  items.reduce((sum, item) => sum + basePremiumOf(item), 0);
71	
72	const quotePremiumOf = (items: readonly Item[]): number =>
73	  policyBasePremiumOf(items) + PROCESSING_FEE;
74	
75	export function runScenario(scenario: Scenario): ScenarioResult {
76	  const quoteStep = scenario.steps[0] as QuoteStep;
77	  return { results: [{ premium: quotePremiumOf(quoteStep.items) }] };
78	}
